#include <iostream>
#include "adv_api/matmul/matmul_tiling.h"
#include "utils/tiling/platform/platform_ascendc.h"
int main() {
 auto *platform = platform_ascendc::PlatformAscendCManager::GetInstance("Ascend910_9362");
 if (!platform) return 1; uint64_t l1 = 0; platform->GetCoreMemSize(platform_ascendc::CoreMemType::L1, l1); std::cout << "L1 bytes=" << l1 << "\n";
 for (auto rows : {128}) for (auto k : {136, 264, 328, 520, 1032, 1208, 1272}) for (auto fixedK : {-1}) {
  const int cols = 256;
  matmul_tiling::MatmulApiTiling t(*platform);
  t.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);
  t.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);
  t.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
  t.SetShape(rows, cols, k); t.SetOrgShape(1025, 1031, k); t.SetFixSplit(rows, cols, fixedK);
  t.SetBias(false); t.SetBufferSpace(-1,-1,-1);
  TCubeTiling data{}; int result=t.GetTiling(data);
  std::cout << rows << "x" << cols << " K=" << k << " fixed=" << fixedK << " ret=" << result
  << " base=" << data.baseM << "," << data.baseN << "," << data.baseK
  << " stepMN=" << data.stepM << "," << data.stepN << " depth=" << data.depthA1 << "," << data.depthB1
  << " step=" << data.stepKa << "," << data.stepKb
  << " proposedBytes=" << (static_cast<uint64_t>(data.baseM) * data.depthA1 + static_cast<uint64_t>(data.baseN) * 6) * data.baseK * 2 << " db=" << data.dbL0A << "," << data.dbL0B << "," << data.dbL0C << "\n";
 }
}
